INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Festplatte dasselbe wie eine SSD?', 2, '[{"text": "Nein", "correct": true, "because": "Mechanisch vs. Flash"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Technologien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt eine Festplatte?', 3, '[{"text": "Dauerhafte Datenspeicherung", "correct": true, "because": "Nichtflüchtig"}, {"text": "Temporäre Verarbeitung", "correct": false, "because": "RAM-Funktion"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Kein Netzwerkfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten hat eine Festplatte?', 5, '[{"text": "Platten", "correct": true, "because": "Speichermedium"}, {"text": "Lese-/Schreibkopf", "correct": true, "because": "Datenbearbeitung"}, {"text": "Papierstreifen", "correct": false, "because": "Kein Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Festplatten sind mechanische Geräte. b) Sie sind schneller als SSDs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSDs schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Festplatte?', 4, '[{"text": "Speicherkapazität", "correct": false, "because": "Kernmerkmal"}, {"text": "Drehzahl", "correct": false, "because": "Leistungsfaktor"}, {"text": "Papiergröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Festplatten flüchtig sind?', 2, '[{"text": "Nein", "correct": true, "because": "Nichtflüchtig"}, {"text": "Ja", "correct": false, "because": "Dauerhafte Speicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle ist typisch für Festplatten?', 3, '[{"text": "SATA", "correct": true, "because": "Standardverbindung"}, {"text": "HDMI", "correct": false, "because": "Videoausgang"}, {"text": "Ethernet", "correct": false, "because": "Netzwerk"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Festplatte?', 5, '[{"text": "Hohe Kapazität", "correct": true, "because": "Große Speichergrößen"}, {"text": "Kosteneffizienz", "correct": true, "because": "Günstiger pro GB"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "SSDs schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Festplatten speichern Daten dauerhaft. b) Sie sind immer extern. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch intern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Festplatte?', 4, '[{"text": "Speicherplatten", "correct": false, "because": "Datenmedium"}, {"text": "Schnittstelle", "correct": false, "because": "Verbindung nötig"}, {"text": "Papierhandbuch", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Festplatten schneller als SSDs?', 2, '[{"text": "Nein", "correct": true, "because": "SSDs schneller"}, {"text": "Ja", "correct": false, "because": "Mechanisch langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Festplattentypen gibt es?', 4, '[{"text": "Interne HDD", "correct": true, "because": "Im Gerät"}, {"text": "Externe HDD", "correct": true, "because": "Portabel"}, {"text": "Papierplatte", "correct": false, "because": "Kein Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Festplatten keine Wartung brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Defragmentierung möglich"}, {"text": "Ja", "correct": false, "because": "Pflege nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Festplatte?', 3, '[{"text": "Kapazität", "correct": true, "because": "Speicherbedarf"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Sekundär zu SSDs"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Festplatten nutzen rotierende Platten. b) Sie sind flüchtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nichtflüchtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei Festplatten?', 5, '[{"text": "Mechanischer Defekt", "correct": true, "because": "Bewegliche Teile"}, {"text": "Datenverlust", "correct": true, "because": "Fehler möglich"}, {"text": "Papierstau", "correct": false, "because": "Nicht physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Festplatte unwichtig?', 3, '[{"text": "Speicherkapazität", "correct": false, "because": "Kernmerkmal"}, {"text": "Zuverlässigkeit", "correct": false, "because": "Datenintegrität"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Festplatte als Boot-Medium genutzt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Betriebssystem startbar"}, {"text": "Nein", "correct": false, "because": "Bootfähig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Festplatten nur für PCs sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Server, Konsolen"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für eine Festplatte zentral?', 4, '[{"text": "Rotierende Platten", "correct": true, "because": "Speichermechanik"}, {"text": "Papierdokumentation", "correct": false, "because": "Irrelevant"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Kein Netzwerkfokus"}]');
